function fillAssumptions(){const f=$('assumptions-form');f.elements.age.value=plan.age;f.elements.end_age.value=+plan.age+(+plan.horizon);f.elements.retirement_age.value=plan.retirement_age;f.elements.return_rate.value=(+plan.return_rate*100).toFixed(1);f.elements.inflation_rate.value=((+plan.inflation_rate||0)*100).toFixed(1);f.elements.withdrawal_rate.value=(+plan.withdrawal_rate*100).toFixed(1);$('currency-display').value=plan.currency||'USD'}
