$('quick-form').onsubmit=e=>e.preventDefault();$('quick-form').oninput=e=>{const k=e.target.name;if(!k)return;const val=Number(e.target.value);if(!Number.isFinite(val))return;if(k==='savings'){if(val>quickState.income){tell('Savings cannot exceed income because expenses cannot be negative.',true);syncQuickDerived();return}quickState.expenses=quickState.income-val}else if(k==='monthly_savings'){const annual=val*12;if(annual>quickState.income){tell('Savings cannot exceed income because expenses cannot be negative.',true);syncQuickDerived();return}quickState.expenses=quickState.income-annual}else if(k==='savings_rate'){const annual=quickState.income*val/100;if(annual>quickState.income){tell('Savings rate cannot exceed 100%.',true);syncQuickDerived();return}quickState.expenses=quickState.income-annual}else if(k==='income'){quickState.income=val}else if(k==='expenses')quickState.expenses=val;else if(k==='return_rate'||k==='withdrawal_rate')quickState[k]=val/100;else quickState[k]=val;if(k==='income'||k==='expenses'||k==='savings'||k==='monthly_savings'||k==='savings_rate')syncQuickDerived();quickResult=null;$('save-state').textContent='Unsaved quick estimate';$('save-state').classList.add('dirty');runQuick()};
