function renderQuick(r){$('quick-target').textContent=money(r.target);$('quick-target-note').textContent=`${money(quickState.expenses)} annual expenses ÷ ${pct(quickState.withdrawal_rate)}`;$('quick-savings').textContent=money(r.savings);$('quick-status').textContent=({already_at_target:'Already at target',target_reached:'Target reached',not_reached_within_horizon:'Beyond horizon',funding_shortfall:'Funding shortfall',unreachable:'Unreachable under assumptions'})[r.status]||r.status;$('quick-years').textContent=r.years_to_target==null?'—':String(r.years_to_target);$('quick-age').textContent=r.retirement_age==null?'—':String(r.retirement_age);$('quick-status').className='status-pill '+(r.status==='target_reached'||r.status==='already_at_target'?'good':r.status==='funding_shortfall'?'alert':'');const rows=r.annual||[],target=r.target,W=680,H=200,L=58,R=18,T=16,B=30,max=Math.max(target,...rows.map(x=>x.balance),1)*1.08,x=i=>L+i/Math.max(1,rows.length-1)*(W-L-R),y=v=>T+(1-v/max)*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" aria-hidden="true">`;for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ece7"/><text x="${L-7}" y="${y(v)+3}" text-anchor="end" fill="#79837e" font-size="9">${compact(v)}</text>`}svg+=`<line x1="${L}" x2="${W-R}" y1="${y(target)}" y2="${y(target)}" stroke="#9aa891" stroke-dasharray="5 5"/><polyline points="${rows.map((v,i)=>`${x(i)},${y(v.balance)}`).join(' ')}" fill="none" stroke="#28675e" stroke-width="3"/>`;[0,rows.length-1].forEach(i=>svg+=`<text x="${x(i)}" y="${H-7}" text-anchor="middle" fill="#79837e" font-size="9">Age ${rows[i]?.age??''}</text>`);$('quick-chart').innerHTML=svg+'</svg>';$('quick-annual').innerHTML=rows.map(v=>`<tr><td>${v.year}</td><td>${v.age}</td><td>${money(v.balance)}</td><td>${money(v.unfunded||0)}</td></tr>`).join('');renderQuickSavings(r.savings_curve||[])}
function renderQuickSavings(points){const W=680,H=170,L=44,R=14,T=12,B=32,max=Math.max(1,quickState.horizon),x=v=>L+v*(W-L-R),y=v=>T+(1-Math.min(v,max)/max)*(H-T-B);let s=`<svg viewBox="0 0 ${W} ${H}" aria-hidden="true">`;for(let i=0;i<=4;i++){const v=max*i/4;s+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ece7"/><text x="${L-5}" y="${y(v)+3}" text-anchor="end" fill="#79837e" font-size="9">${Math.round(v)}y</text>`}let segment=[];const flush=()=>{if(segment.length>1)s+=`<polyline points="${segment.join(' ')}" fill="none" stroke="#28675e" stroke-width="2"/>`;segment=[]};for(const p of points){const valid=p.years_to_target!==null&&p.years_to_target!==undefined&&['target_reached','already_at_target'].includes(p.status);if(valid)segment.push(`${x(p.savings_rate)},${y(p.years_to_target)}`);else flush()}flush();for(const p of points){const valid=p.years_to_target!==null&&p.years_to_target!==undefined&&['target_reached','already_at_target'].includes(p.status),yy=valid?y(p.years_to_target):y(max);s+=`<circle cx="${x(p.savings_rate)}" cy="${yy}" r="3" fill="${valid?'#28675e':'#be805d'}"><title>${(p.savings_rate*100).toFixed(0)}% savings: ${valid?`${p.years_to_target} years`:(p.status||'not reached')}</title></circle>`}s+=`<text x="${L}" y="${H-7}" fill="#79837e" font-size="9">0%</text><text x="${W-R}" y="${H-7}" text-anchor="end" fill="#79837e" font-size="9">100% savings rate</text></svg>`;$('quick-savings-chart').innerHTML=s}
