async function projectPlan(p=plan){return api('/api/project',{plan:p})}async function runProjection(quiet=false){clearTimeout(autoTimer);const requested=JSON.stringify(plan);const b=$('run-projection');b.disabled=true;b.textContent='Calculating…';try{const result=await projectPlan(JSON.parse(requested));if(requested!==JSON.stringify(plan))return;projection=result;simulation=null;touchAfterRun();renderTables();if(quiet!==true)tell('Projection updated.')}catch(e){if(quiet===true){$('projection-note').textContent=`Projection not updated: ${e.message}`;$('health-status').textContent='Needs attention'}else tell(e.message,true)}finally{b.disabled=false;b.innerHTML='Update projection <span>↗</span>'}}
function touchAfterRun(){showSaveState()}$('run-projection').onclick=()=>runProjection();$('run-retirement').onclick=()=>runProjection();$('nominal-toggle').onchange=()=>{if(projection)renderSummary()};$('table-toggle').onclick=()=>{const on=$('annual-wrap').hidden;$('annual-wrap').hidden=!on;$('table-toggle').textContent=on?'Hide annual figures ↑':'Show annual figures ↓';$('table-toggle').setAttribute('aria-expanded',String(on))};
async function runSimulation(){if(!user){tell('Sign in and save this plan before running a simulation.',true);openAuth();return}try{if(!(await ensureSaved()))return;const data=await api(`/api/plans/${saved.id}/run`,{kind:'simulate',settings:{trials:+$('trials').value,seed:+$('seed').value,volatility:+$('volatility').value/100,mode:'parametric'}});pollJob(data.job.id,JSON.stringify(plan))}catch(e){tell(e.message,true)}}$('run-simulation').onclick=runSimulation;
async function pollJob(id,inputSnapshot,attempt=0){if(inputSnapshot!==JSON.stringify(plan))return;$('simulation-result').innerHTML='<span class="quiet-icon">⌁</span><p>Simulation running…</p>';try{const d=await api(`/api/jobs/${id}`),j=d.job;if(inputSnapshot!==JSON.stringify(plan))return;if(['complete','completed','succeeded'].includes(j.status)){simulation=j.result;renderSimulation(j.result);return}if(['failed','cancelled','canceled'].includes(j.status))throw Error(j.error||'Simulation did not complete.');if(attempt>=600)throw Error('The simulation is taking too long to finish. Try fewer trials.');setTimeout(()=>pollJob(id,inputSnapshot,attempt+1),700)}catch(e){$('simulation-result').textContent=e.message;tell(e.message,true)}}function renderSimulation(r){const funded=r.outcomes?.essential_spending_funded,rate=funded?.rate==null?'—':pct(funded.rate),bands=r.annual_bands||[];const W=500,H=125,L=38,R=8,T=8,B=20,max=Math.max(1,...bands.map(x=>+x.p90||0)),x=i=>L+i/Math.max(1,bands.length-1)*(W-L-R),y=v=>T+(1-v/max)*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Simulation median and tenth to ninetieth percentile range">`;for(let i=0;i<=2;i++){const v=max*i/2;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e9ece7"/><text x="${L-4}" y="${y(v)+3}" text-anchor="end" fill="#79837e" font-size="8">${compact(v)}</text>`}if(bands.length){const upper=bands.map((b,i)=>`${x(i)},${y(b.p90)}`).join(' '),lower=bands.slice().reverse().map((b,j)=>`${x(bands.length-1-j)},${y(b.p10)}`).join(' '),median=bands.map((b,i)=>`${x(i)},${y(b.median)}`).join(' ');svg+=`<polygon points="${upper} ${lower}" fill="#dcece3"/><polyline points="${median}" fill="none" stroke="#28675e" stroke-width="2"/>`;}svg+='</svg>';$('simulation-result').innerHTML=`${r.status==='no_complete_periods'?'<p class="notice error">No complete historical periods cover the selected horizon. Shorter or incomplete windows were not counted as successes.</p>':''}<div class="sim-outcome"><span>ESSENTIAL SPENDING FUNDED</span><strong>${esc(rate)}</strong><small>${funded?.numerator==null||funded?.denominator==null?'Outcome data unavailable':`${funded.numerator} of ${funded.denominator} modeled paths`}${funded?.excluded?` · ${funded.excluded} excluded`:''}</small></div><div class="sim-stats"><div>Ending assets median <strong>${money(r.ending_assets?.median)}</strong></div><div>10th–90th percentile <strong>${money(r.ending_assets?.p10)} – ${money(r.ending_assets?.p90)}</strong></div><div>Portfolio survives <strong>${r.outcomes?.portfolio_survives?.rate==null?'—':pct(r.outcomes.portfolio_survives.rate)}</strong></div><div>Desired lifestyle funded <strong>${r.outcomes?.desired_lifestyle_funded?.rate==null?'—':pct(r.outcomes.desired_lifestyle_funded.rate)}</strong></div></div>${bands.length?`<div class="simulation-band-chart">${svg}<small>Year ${bands[0].year} through ${bands[bands.length-1].year} · median with 10th–90th percentile range</small></div>`:''}`}
function scenarioPlan(s){return s.data?s.data.plan:s.plan}
function scenarioName(s){return s.data?.name||s.name||'Scenario'}
async function refreshScenarios(){if(saved){const d=await api(`/api/plans/${saved.id}/scenarios`);scenarios=d.scenarios||[]}renderScenarios()}
async function renderScenarios(){const wrap=$('scenario-list');wrap.innerHTML='';if(!scenarios.length){wrap.innerHTML='<div class="panel empty-state">No scenarios saved. Create one from the current plan to compare possible futures.</div>';return}for(const s of scenarios){const p=scenarioPlan(s),name=scenarioName(s),el=document.createElement('article');el.className='panel scenario-card';el.innerHTML=`<div class="panel-head"><div><span class="scenario-tag">SCENARIO</span><h2>${esc(name)}</h2></div><button class="icon-button danger-text" data-remove-scenario="${esc(s.id)}" aria-label="Remove ${esc(name)}">×</button></div><p class="small-note">Retire at ${p.retirement_age}; ${p.accounts?.length||0} accounts · ${p.streams?.length||0} cash flows</p><div class="scenario-result" id="scenario-${esc(s.id)}">Calculating…</div><div class="button-row"><button class="button secondary" data-compare="${esc(s.id)}">Compare</button><button class="button text-button" data-open-scenario="${esc(s.id)}">Open as current plan</button></div>`;wrap.append(el);projectPlan(p).then(r=>{const target=$(`scenario-${s.id}`),year=r.years_to_target;if(target)target.textContent=(year==null?'Target not reached':`FI age ${+p.age+year} · Target ${money(r.target)}`)+(r.earliest_fi_age!=null&&(year==null||r.earliest_fi_age<+p.age+year)?` · assets reach target at ${r.earliest_fi_age}`:'')}).catch(e=>{const target=$(`scenario-${s.id}`);if(target)target.textContent=e.message})}}
async function saveScenario(){const name=$('scenario-name').value.trim();if(!name){$('scenario-name').focus();return}try{if(user){if(!(await ensureSaved()))return;await api(`/api/plans/${saved.id}/scenarios`,{name,plan:structuredClone(plan)})}else scenarios.push({id:uid(),name,plan:structuredClone(plan)});$('scenario-dialog').close();await refreshScenarios();tell(user?'Scenario saved to this plan.':'Scenario saved for this session.')}catch(e){tell(e.message,true)}}
$('save-scenario').onclick=()=>$('scenario-dialog').showModal();$('new-scenario').onclick=()=>$('scenario-dialog').showModal();$('scenario-form').onsubmit=e=>{e.preventDefault();saveScenario()};$('scenario-close').onclick=$('scenario-cancel').onclick=()=>$('scenario-dialog').close();
