function chartForCompare(results){const currencies=results.map(r=>r.metadata?.currency||'USD'),bases=results.map(r=>r.metadata?.price_basis||'unknown');if(currencies[0]!==currencies[1]||bases[0]!==bases[1])return '<p class="chart-empty">These plans use different currencies or price bases. Convert them with explicit assumptions before comparing their asset paths.</p>';const maps=results.map(r=>new Map((r.annual||[]).map(row=>[row.age,+row.balance||0]))),ages=[...maps[0].keys()].filter(age=>maps[1].has(age)).sort((a,b)=>a-b);if(!ages.length)return '<p class="chart-empty">These plan horizons have no ages in common, so their asset paths cannot be aligned.</p>';const vals=ages.flatMap(age=>maps.map(m=>m.get(age))),targets=results.map(r=>+r.target||0),W=760,H=250,L=60,R=20,T=18,B=34,max=Math.max(...targets,...vals,1)*1.08,x=i=>L+i/Math.max(1,ages.length-1)*(W-L-R),y=v=>T+(1-v/max)*(H-T-B);let out=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Projected assets aligned by age for the current plan and scenario">`;for(let i=0;i<=4;i++){const val=max*i/4;out+=`<line x1="${L}" x2="${W-R}" y1="${y(val)}" y2="${y(val)}" stroke="#e9ece7"/><text x="${L-8}" y="${y(val)+4}" text-anchor="end" fill="#79837e" font-size="10">${compact(val)}</text>`}results.forEach((r,j)=>{out+=`<line x1="${L}" x2="${W-R}" y1="${y(targets[j])}" y2="${y(targets[j])}" stroke="${j?'#be805d':'#28675e'}" stroke-dasharray="4 5" opacity=".7"/>`;const pts=ages.map((age,i)=>`${x(i)},${y(maps[j].get(age))}`).join(' ');out+=`<polyline points="${pts}" fill="none" stroke="${j?'#be805d':'#28675e'}" stroke-width="2.5"/>`});[0,Math.floor((ages.length-1)/2),ages.length-1].forEach(i=>out+=`<text x="${x(i)}" y="${H-9}" text-anchor="middle" fill="#79837e" font-size="10">Age ${ages[i]}</text>`);return out+'</svg><p class="small-note">Asset paths aligned by age. Each plan target and FI age are shown separately.</p>'}
