function renderObservations(){const rows=[...observations].sort((a,b)=>String(b.date).localeCompare(String(a.date)));$('observations-table').innerHTML=rows.map(o=>`<tr><td>${esc(o.date)}</td><td>${money(o.balance)}</td><td>${esc(o.note||'—')}</td><td class="row-actions"><button class="link-button danger-text" data-delete-observation="${esc(o.id)}" aria-label="Remove observation from ${esc(o.date)}">Remove</button></td></tr>`).join('');$('observations-empty').hidden=rows.length>0;if(!rows.length){$('latest-balance').textContent='—';$('latest-date').textContent='No observation yet';$('observed-projection').textContent='—';$('observed-difference').textContent='—';return}const latest=rows[0];$('latest-balance').textContent=money(latest.balance);$('latest-date').textContent=latest.date;const base=String(plan.valuation_date||'').slice(0,10),obs=String(latest.date||'').slice(0,10),parts=base.match(/^(\d{4})-(\d{2})/)||[],date=obs.match(/^(\d{4})-(\d{2})/);let months=null;if(parts.length&&date)months=obs<base?-1:(+date[1]- +parts[1])*12+(+date[2]- +parts[2]);const estimate=projectedPortfolioAt(months);$('observed-projection').textContent=estimate==null?(months==null?'Baseline unavailable':months<0?'Before plan baseline':'Outside projection'):money(estimate);$('observed-difference').textContent=estimate==null?'—':money(latest.balance-estimate);if(typeof renderProgressChart==='function')renderProgressChart()};
